{
  "findings": [
    {
      "check_id": "UNKNOWN",
      "title": "Overly permissive 'not_actions' wildcard in role definition",
      "resource": "azurerm_role_definition.example2",
      "severity": "HIGH",
      "explanation": "Using a wildcard ('*') in 'not_actions' effectively denies all actions, which can lead to unintended consequences and may block legitimate operations. This configuration should be explicitly defined to avoid overly broad restrictions."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Use of built-in 'Guest' role in role assignment",
      "resource": "azurerm_role_assignment.example2",
      "severity": "MEDIUM",
      "explanation": "Assigning the built-in 'Guest' role can lead to excessive permissions for external users. Custom roles with least privilege should be used instead to minimize risk."
    }
  ],
  "patched_code": "resource "azurerm_role_definition" "example2" {
  name        = "my-custom-role"
  scope       = data.azurerm_subscription.primary.id
  description = "This is a custom role created via Terraform"

  permissions {
    actions     = []
    not_actions = ["Microsoft.Authorization/*/Delete", "Microsoft.Authorization/*/Write"]
  }

  assignable_scopes = [
    data.azurerm_subscription.primary.id, 
  ]
}

resource "azurerm_role_assignment" "example2" {
  name               = "00000000-0000-0000-0000-000000000000"
  scope              = data.azurerm_subscription.primary.id
  role_definition_name = azurerm_role_definition.example2.name
  role_definition_id = azurerm_role_definition.example2.role_definition_resource_id
  principal_id       = data.azurerm_client_config.example.object_id
}
",
  "fix_summary": "Replaced the wildcard in 'not_actions' with specific deny actions to avoid overly broad restrictions. Updated the role assignment to use the custom role instead of the built-in 'Guest' role."
}
